import re, datetime, json
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
AY = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ORD = {1: 'birinci', 2: 'ikinci', 3: 'üçüncü', 4: 'dördüncü'}
def _w3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        s.append(TENS[t])
    if o:
        s.append(ONES[o])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, nm in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append('bin' if (val == 1000 and q == 1) else _w3(q) + ' ' + nm)
    if n:
        parts.append(_w3(n))
    return ' '.join(parts)
def fl(x):
    try:
        return float(x)
    except Exception:
        return 0.0
def sfx(text):
    w = text.strip().split()[-1]
    low = w.lower()
    v = 'ı'
    for ch in reversed(low):
        if ch in 'aı':
            v = 'ı'; break
        if ch in 'ei':
            v = 'i'; break
        if ch in 'ou':
            v = 'u'; break
        if ch in 'öü':
            v = 'ü'; break
    c = 't' if low[-1] in 'fstkçşhp' else 'd'
    s = c + v + 'r'
    return text + ("'" + s if w[:1].isupper() else s)
CUR = {'TL': ('Türk Lirası', 'lira', 'kuruş'), 'USD': ('Dolar', 'dolar', 'sent'), 'EUR': ('Euro', 'euro', 'sent'), 'GBP': ('İngiliz Sterlini', 'İngiliz Sterlini', 'peni')}
def amt(x, cur):
    x = round(abs(fl(x)) + 1e-9, 2)
    i = int(x)
    c = int(round((x - i) * 100))
    full, unit, sub = CUR[cur]
    if c:
        return words(i) + ' ' + unit + ' ' + words(c) + ' ' + sub
    return words(i) + ' ' + full
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(s):
    d = pdate(s)
    if not d:
        return str(s)
    return str(d.day) + ' ' + AY[d.month] + ' ' + str(d.year)
def sdate_sfx(s):
    d = pdate(s)
    if not d:
        return str(s)
    yw = words(d.year)
    return sdate(s) + "'" + sfx(yw)[len(yw):].lstrip("'")
def digits(s):
    return ' '.join(DIG[int(ch)] for ch in str(s) if ch.isdigit())
def today():
    try:
        m = re.match(r'(\d{4})-(\d{1,2})-(\d{1,2})', str(vars.get('now') or ''))
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except Exception:
        return datetime.date.today()
def lst(k):
    return [x for x in str(vars.get(k) or '').split(',') if x]
def env(data):
    meta = dict(ani='', lang='tr')
    return dict(data=data, call=meta)
def ok_body(result):
    d = result.get('data') if isinstance(result, dict) else None
    sc = str(result.get('status_code') or '200') if isinstance(result, dict) else ''
    if isinstance(d, dict) and sc.startswith('2') and str((d.get('result') or {}).get('returnCode')) == '1' and isinstance(d.get('data'), dict):
        return d.get('data')
    return None

try:
    b = config.get('body') if isinstance(config.get('body'), dict) else {}
    w = re.sub(r'\D', '', str(b.get('new_week') or ''))[:1]
    vars['req_week'] = w
    vars['opts_read'] = 'yes' if str(b.get('options_already_read') or '').lower().startswith('y') else 'no'
    vars['week_block'] = ''
    if w == str(vars.get('cur_week')):
        vars['week_block'] = 'current'
    elif w not in lst('week_allowed'):
        vars['week_block'] = 'not_offered'
    idx = str(vars.get('sel_idx') or '')
    if vars['week_block']:
        config['url'] = str(config.get('url') or '').replace('statement.week.decide', 'statement.week.get')
        config['body'] = env({'cardNumber': str(vars.get('card_' + idx) or '')})
    else:
        config['body'] = env({'cardNumber': str(vars.get('card_' + idx) or ''), 'newStatementWeek': w, 'statementDay': int(fl(vars.get('cur_day')))})
except Exception:
    pass

