            else:
                out.append(lead + 'Türk Lirası borcunuz ' + amt(sd, c) + ', ödenmesi gereken minimum tutar ' + amt(mp, c) + ', kalan toplam borcunuz ' + amt(rd, c) + ', kalan minimum ödeme tutarınız ' + sfx(amt(rm, c)) + '.')
