    if dd and dd == t0:
        out.append('Borçlarınız için son ödeme tarihiniz bugündür.')
    elif passed:
        out.append('Borçlarınız için son ödeme tarihiniz olan ' + sdate(due) + ' geçmiştir.')
        tots = [amt(x.get('totalDebt'), c) for c, x in present if fl(x.get('totalDebt')) > 0]
        if tots:
            out.append('Güncel toplam borcunuz ' + sfx(' ve '.join(tots)) + '.')
    elif dd:
        out.append('Borçlarınız için son ödeme tarihiniz ' + sdate_sfx(due) + '.')
    return ' '.join(out)
